#!/usr/bin/env node
'use strict';
// report.js: imprime un renglón por fila, como mucho 50
const rows = require('../data/rows.json');

function report(rs, limit = 50) {
  return rs.slice(0, limit).map((r) => `${r.id}: ${r.total}`).join('\n');
}

if (require.main === module) console.log(report(rows));
module.exports = { report };

