#!/usr/bin/env node
'use strict';
// tasks.js: `list` imprime las tareas
const tasks = require('../data/tasks.json');

function list(ts) { return ts.map((t) => `${t.id} ${t.title} (${t.due})`).join('\n'); }

if (require.main === module) {
  const cmd = process.argv[2] || 'list';
  if (cmd === 'list') console.log(list(tasks));
  else { console.error(`no conozco el subcomando ${cmd}`); process.exit(2); }
}
module.exports = { list };

tree.test.js:
'use strict';
const assert = require('assert');
const { report } = require('./scripts/report.js');
const { list } = require('./scripts/tasks.js');
assert.strictEqual(report([{ id: 1, total: 5 }]), '1: 5');
assert.ok(list(require('./data/tasks.json')).includes('Cerrar el mes'));
console.log('ok');

